pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        c.initialize();

        c.updateRoundImplementation(payable(address(0xdeadbeef)));
        c.updateAlloSettings(address(0xdeadcafe));

        address ownerObserved = c.owner();

        assertTrue(ownerObserved != address(0), "Owner should be non-zero after initialization");
    }
}
